package io.github.ningpp.compat;

import java.nio.file.Path;
import java.nio.file.Paths;

/** Replacement for System.IO.Path static methods (generated by CSharpToJava converter). */
public class PathHelper {
    /** Mirrors Path.IsPathRooted */
    public static boolean isPathRooted(String path) {
        return path != null && Paths.get(path).isAbsolute();
    }
    /** Mirrors Path.GetFullPath */
    public static String getFullPath(String path) {
        return Paths.get(path).toAbsolutePath().normalize().toString();
    }
    /** Mirrors Path.GetDirectoryName — returns parent directory path, or null if no parent */
    public static String getDirectoryName(String path) {
        Path p = Paths.get(path).getParent();
        return p != null ? p.toString() : null;
    }
    /** Mirrors Path.GetFileName */
    public static String getFileName(String path) {
        Path p = Paths.get(path).getFileName();
        return p != null ? p.toString() : null;
    }
    /** Mirrors Path.GetFileNameWithoutExtension */
    public static String getFileNameWithoutExtension(String path) {
        String name = getFileName(path);
        if (name == null) return null;
        int dot = name.lastIndexOf('.');
        return dot > 0 ? name.substring(0, dot) : name;
    }
    /** Mirrors Path.Combine(string, string) */
    public static String combine(String path1, String path2) {
        if (path1 == null || path1.isEmpty()) return path2;
        if (path2 == null || path2.isEmpty()) return path1;
        if (Paths.get(path2).isAbsolute()) return path2;
        return Paths.get(path1, path2).toString();
    }
    /**
     * Mirrors Path.Combine(ReadOnlySpan&lt;char&gt;, params ReadOnlySpan&lt;string&gt;):
     * C# overload resolution prefers this normal form over params string[] when the
     * first argument is a string literal (implicit string → ReadOnlySpan&lt;char&gt;),
     * so converted call sites arrive with the span-wrapped first path (real chain:
     * FilePathUtil state-machine cases). The span is just the first path's text.
     */
    public static String combine(ReadOnlySpan<Character> path1, String... paths) {
        String[] all = new String[paths.length + 1];
        all[0] = path1 == null ? null : path1.toString();
        System.arraycopy(paths, 0, all, 1, paths.length);
        return combine(all);
    }
    /** Mirrors Path.Combine(params string[] paths). */
    public static String combine(String... paths) {
        if (paths == null || paths.length == 0) return "";
        String combined = "";
        for (String path : paths) {
            combined = combine(combined, path);
        }
        return combined;
    }
    /** Mirrors Path.GetExtension */
    public static String getExtension(String path) {        String name = getFileName(path);
        if (name == null) return null;
        int dot = name.lastIndexOf('.');
        return dot >= 0 ? name.substring(dot) : "";
    }

    /** Mirrors Path.ChangeExtension — replaces (or removes) the extension of a path. */
    public static String changeExtension(String path, String extension) {
        if (path == null) {
            return null;
        }
        String baseName = path;
        int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
        int dot = path.lastIndexOf('.');
        if (dot > lastSeparator) {
            baseName = path.substring(0, dot);
        }
        if (extension == null || extension.isEmpty()) {
            return baseName;
        }
        String ext = extension.startsWith(".") ? extension : "." + extension;
        return baseName + ext;
    }

    /** Mirrors Path.GetRandomFileName() — an 8.3-style random file name. */
    public static String getRandomFileName() {
        return UUID.randomUUID().toString("N").substring(0, 8) + ".tmp";
    }

    /** Mirrors Path.GetTempPath() — trailing separator included, as in .NET. */
    public static String getTempPath() {
        String temp = System.getProperty("java.io.tmpdir");
        if (temp == null || temp.isEmpty()) {
            temp = ".";
        }
        return temp.endsWith(java.io.File.separator) ? temp : temp + java.io.File.separator;
    }

    /** Mirrors Path.GetTempFileName() — creates an empty temporary file and returns its absolute path. */
    public static String getTempFileName() {        try {
            java.io.File tempFile = java.io.File.createTempFile("cs2j", ".tmp");
            return tempFile.getAbsolutePath();
        } catch (java.io.IOException e) {
            throw new RuntimeException("Failed to create temporary file", e);
        }
    }
}
